package dev.mando;
import java.net.URI;import java.net.http.*;import java.time.Duration;import org.bukkit.Bukkit;import org.bukkit.entity.Player;
public final class UpdateChecker{
 private final MandoPlugin plugin;public UpdateChecker(MandoPlugin p){plugin=p;}
 public void checkAsync(){if(!plugin.getConfig().getBoolean("updates.enabled",true))return;String channel=plugin.getConfig().getString("updates.channel","STABLE").toUpperCase();String endpoint=channel.equals("TEST")?"https://api.github.com/repos/Italoplcl/comandos/releases":"https://api.github.com/repos/Italoplcl/comandos/releases/latest";try{HttpRequest q=HttpRequest.newBuilder(URI.create(endpoint)).timeout(Duration.ofSeconds(5)).header("Accept","application/vnd.github+json").header("User-Agent","Mando-UpdateChecker").build();HttpClient.newHttpClient().sendAsync(q,HttpResponse.BodyHandlers.ofString()).thenAccept(r->{if(r.statusCode()<200||r.statusCode()>=300){plugin.getLogger().warning("Update checker: GitHub respondió "+r.statusCode());return;}String latest=value(r.body(),"tag_name"),page=value(r.body(),"html_url"),installed=plugin.getPluginMeta().getVersion();if(latest.isBlank()){plugin.getLogger().info("GitHub: no hay una release "+channel.toLowerCase()+" publicada para comparar.");return;}plugin.getLogger().info("GitHub ("+channel+"): publicada "+latest+" | instalada "+installed+" | "+page);if(!normalize(latest).equals(normalize(installed)))Bukkit.getScheduler().runTask(plugin,()->notifyOps(latest,installed,page,channel));}).exceptionally(ex->{plugin.getLogger().warning("No se pudo comprobar actualizaciones: "+ex.getMessage());return null;});}catch(Exception ex){plugin.getLogger().warning("Update checker no disponible: "+ex.getMessage());}}
 private String value(String json,String key){int k=json.indexOf(key);if(k<0)return "";int colon=json.indexOf(':',k+key.length());if(colon<0)return "";int q1=json.indexOf('"',colon+1),q2=q1<0?-1:json.indexOf('"',q1+1);return q1>=0&&q2>q1?json.substring(q1+1,q2):"";}
 private String normalize(String v){return v==null?"":v.trim().toLowerCase().replaceFirst("^v","");}
 private void notifyOps(String latest,String installed,String page,String channel){for(Player p:Bukkit.getOnlinePlayers())if(p.isOp()&&plugin.authGuard().authenticated(p))p.sendMessage("§6Mando §8» §eRelease "+channel+" disponible: §f"+latest+" §7(instalada "+installed+") §8"+page);}
}